const recalculateInvoicePayments = `-- name: RecalculateInvoicePayments :one
WITH alloc AS (
    SELECT COALESCE(SUM(allocated_amount), 0)::numeric(14, 3) AS total_allocated
    FROM finance.payment_allocation
    WHERE invoice_id = $1
)
UPDATE finance.invoice i SET
    amount_paid = a.total_allocated,
    balance_due = GREATEST(COALESCE(i.total, i.total_amount, 0) - a.total_allocated, 0),
    status = CASE
        WHEN a.total_allocated <= 0 AND i.status IN ('paid', 'partially_paid') THEN 'issued'
        WHEN COALESCE(i.total, i.total_amount, 0) - a.total_allocated <= 0 AND a.total_allocated > 0 THEN 'paid'
        WHEN a.total_allocated > 0 THEN 'partially_paid'
        ELSE i.status
    END,
    updated_at = now()
FROM alloc a
WHERE i.id = $1
RETURNING i.id, i.invoice_number, i.quotation_id, i.contact_id, i.deal_id, i.status, i.issue_date, i.due_date, i.subtotal, i.discount, i.vat_rate, i.vat_amount, i.total, i.amount_paid, i.balance_due, i.currency, i.notes, i.terms, i.created_at, i.updated_at, i.client_id, i.vat_enabled, i.vat_percentage, i.other_tax_amount, i.discount_type, i.discount_value, i.discount_amount, i.total_amount, i.language, i.approval_status, i.approval_revision, i.content_hash, i.pdf_storage_path, i.delivery_channel, i.delivered_at, i.notes_en, i.notes_ar, i.created_by_id, i.sales_owner_id, i.signed_by_id, i.signed_at, i.signer_signature_url
`

